const native=!!window.Capacitor?.isNativePlatform?.();
if(native)startNative().catch(error=>console.error('Native services failed',error));

async function startNative(){
 const [{Capacitor},{AdMob,AdmobConsentStatus},{Purchases},{Browser}]=await Promise.all([import('@capacitor/core'),import('@capacitor-community/admob'),import('@revenuecat/purchases-capacitor'),import('@capacitor/browser')]);
 const platform=Capacitor.getPlatform(),config=window.FITNESS_COPILOT_NATIVE_CONFIG||{};
 let adsReady=false,interstitialReady=false,purchasesReady=false;
 const adId=kind=>config.admob?.[platform+kind[0].toUpperCase()+kind.slice(1)]||'';
 async function initializeAds(){if(adsReady)return;await AdMob.initialize({initializeForTesting:!!config.admob?.testing});let consent=await AdMob.requestConsentInfo();if(consent.isConsentFormAvailable&&consent.status===AdmobConsentStatus.REQUIRED)consent=await AdMob.showConsentForm();adsReady=!!consent.canRequestAds;if(adsReady)await prepareInterstitial();}
 async function prepareInterstitial(){const id=adId('interstitial');if(!id)return;try{await AdMob.prepareInterstitial({adId:id,isTesting:!!config.admob?.testing});interstitialReady=true;}catch{interstitialReady=false;}}
 async function showInterstitial(){await initializeAds();if(!adsReady||!interstitialReady)return false;const appState=JSON.parse(localStorage.getItem('forma-v1')||'{}');if(window.FORMA_BILLING?.isPro()||appState.activeSession||document.querySelector('#modal[open],#commerce-modal[open]'))return false;interstitialReady=false;try{await AdMob.showInterstitial();return true;}finally{await prepareInterstitial();}}
 async function initializePurchases(){const key=config.revenueCat?.[platform+'ApiKey'];if(!key){window.dispatchEvent(new CustomEvent('fitness:products-error'));return false;}if(purchasesReady)return purchasesReady;await Purchases.configure({apiKey:key});purchasesReady=true;const [info,offerings]=await Promise.all([Purchases.getCustomerInfo(),Purchases.getOfferings()]);syncEntitlement(info.customerInfo);const packages=offerings.current?.availablePackages||[];let eligibility={};if(platform==='ios'&&packages.length){try{eligibility=await Purchases.checkTrialOrIntroductoryPriceEligibility({productIdentifiers:packages.map(item=>item.product.identifier)});}catch{eligibility={};}}window.dispatchEvent(new CustomEvent('fitness:products-ready',{detail:{products:packages.map(item=>({plan:item.packageType==='MONTHLY'?'monthly':item.packageType==='ANNUAL'?'yearly':null,price:item.product.priceString,intro:item.product.introPrice&&(platform!=='ios'||eligibility[item.product.identifier]?.status===2)?{price:item.product.introPrice.price,periodUnit:item.product.introPrice.periodUnit,periodNumberOfUnits:item.product.introPrice.periodNumberOfUnits}:null})).filter(item=>item.plan)}}));return true;}
 function syncEntitlement(customerInfo){const active=customerInfo?.entitlements?.active||{},pro=active.pro;window.FORMA_BILLING?.setEntitlement(pro?(pro.periodType==='TRIAL'?'trial':'active'):'inactive',pro?.expirationDate||null);}
 async function checkout(product){if(!await initializePurchases())throw new Error('Abonelik şu anda mağazada kullanılamıyor.');const offerings=await Purchases.getOfferings(),packages=offerings.current?.availablePackages||[],wanted=product==='monthly'?'MONTHLY':'ANNUAL',selected=packages.find(item=>item.packageType===wanted);if(!selected)throw new Error('Seçilen abonelik seçeneği şu anda mağazada kullanılamıyor.');const result=await Purchases.purchasePackage({aPackage:selected});syncEntitlement(result.customerInfo);}
 async function restorePurchases(){if(!await initializePurchases())throw new Error('Satın alımlar geri yüklenemedi.');const result=await Purchases.restorePurchases();syncEntitlement(result.customerInfo);}
 window.FORMA_BILLING?.setAdAdapter({showInterstitial});
 window.addEventListener('forma:checkout',event=>checkout(event.detail?.product).then(()=>window.dispatchEvent(new CustomEvent('fitness:purchase-result',{detail:{ok:true}}))).catch(error=>{console.error('Checkout failed',error);window.dispatchEvent(new CustomEvent('fitness:purchase-result',{detail:{ok:false,message:error?.message||'Satın alma işlemi tamamlanamadı.'}}));}));
 window.addEventListener('fitness:restore-purchases',()=>restorePurchases().then(()=>window.dispatchEvent(new CustomEvent('fitness:restore-result',{detail:{ok:true}}))).catch(error=>{console.error('Restore failed',error);window.dispatchEvent(new CustomEvent('fitness:restore-result',{detail:{ok:false,message:error?.message||'Satın alımlar geri yüklenemedi.'}}));}));
 window.addEventListener('fitness:open-video',event=>{const url=event.detail?.url;if(/^https:\/\//.test(url||''))Browser.open({url,presentationStyle:'fullscreen'}).catch(error=>console.error('Video browser failed',error));});
 window.addEventListener('fitness:open-link',event=>{const url=event.detail?.url;if(/^https:\/\//.test(url||''))Browser.open({url,presentationStyle:'fullscreen'}).catch(error=>console.error('App policy browser failed',error));});
 window.addEventListener('fitness:privacy-options',async()=>{try{const info=await AdMob.requestConsentInfo();if(info.privacyOptionsRequirementStatus==='REQUIRED'){await AdMob.showPrivacyOptionsForm();}else window.dispatchEvent(new CustomEvent('fitness:privacy-options-result',{detail:{available:false}}));}catch(error){console.error('Privacy options failed',error);window.dispatchEvent(new CustomEvent('fitness:privacy-options-result',{detail:{ok:false}}));}});
 window.addEventListener('fitness:manage-subscriptions',()=>Browser.open({url:platform==='ios'?'https://apps.apple.com/account/subscriptions':'https://play.google.com/store/account/subscriptions',presentationStyle:'fullscreen'}).catch(error=>console.error('Subscription management failed',error)));
 await initializePurchases().catch(error=>{console.error('Purchases initialization failed',error);window.dispatchEvent(new CustomEvent('fitness:products-error'));});
 await initializeAds().catch(console.error);
}
